</div>
<aside class="col g12" style="position:sticky;top:12px" data-bc-msg><div class="row between"><h2 class="sl-ct">What customers get</h2><span class="mut sm">Sample: <?= h($d['sample']['name']) ?></span></div>
<div class="bc-pv">
<div class="ph wa" data-pv="whatsapp"><div class="ph-sc"><div class="ph-st"><span><?= date('H:i') ?></span><span class="ph-ic" aria-hidden="true"><i class="sig"><b></b><b></b><b></b><b></b></i><i class="wifi"></i><i class="bat"><b></b></i></span></div><div class="ph-hd"><span class="ph-av"><?= h(sl_initials($site)) ?></span><span class="col"><span><?= h($site) ?></span><span style="font:400 13px Figtree;opacity:.75">WhatsApp</span></span></div><div class="ph-bd"><span class="ph-day">Today</span><div class="bub" data-pv-att hidden><span class="doc"><i class="ic ic-sm i-file" aria-hidden="true"></i><span data-pv-attn></span></span></div><div class="bub"><span class="hd" data-pv-s></span><span data-pv-m style="white-space:pre-line"></span><span class="tm"><?= date('H:i') ?> ✓✓</span></div></div></div></div>
<div class="ph sms" data-pv="sms"><div class="ph-sc"><div class="ph-st"><span><?= date('H:i') ?></span><span class="ph-ic" aria-hidden="true"><i class="sig"><b></b><b></b><b></b><b></b></i><i class="wifi"></i><i class="bat"><b></b></i></span></div><div class="ph-hd"><span class="ph-av"><?= h(sl_initials($site)) ?></span><span><?= h(strtoupper(mb_substr($site, 0, 11))) ?></span></div><div class="ph-bd"><span class="ph-day">Text Message · Today</span><div class="bub" data-pv-m style="white-space:pre-line"></div></div></div></div>
<div class="ph em" data-pv="email"><div class="ph-sc"><div class="ph-st"><span><?= date('H:i') ?></span><span class="ph-ic" aria-hidden="true"><i class="sig"><b></b><b></b><b></b><b></b></i><i class="wifi"></i><i class="bat"><b></b></i></span></div><div class="ph-hd"><span class="ph-av"><?= h(sl_initials($site)) ?></span><span class="col"><span><?= h($site) ?></span><span style="font:400 13px Figtree;color:#777">to <?= h($d['sample']['email']) ?></span></span></div><div class="ph-bd"><div class="card"><b class="s" data-pv-s></b><span data-pv-m style="white-space:pre-line"></span><span class="cta">Open my account</span></div></div></div></div>
<span class="mut" id="bc-noch" hidden>Pick at least one channel.</span>
</div></aside></div>
<script>
(function(){
  var AJ = 'ajax/tools/push_notifications_ajax.php', R = <?= json_encode($rt) ?>, type = <?= json_encode($d['type']) ?>, media = '', $ = function(i){ return document.getElementById(i); };
  function chans(){ return Array.prototype.filter.call(document.querySelectorAll('[data-ch]'), function(b){ return b.classList.contains('on'); }).map(function(b){ return b.getAttribute('data-ch'); }); }
  var own = 'all', CJ = 'ajax/tools/push_notifications_consolidation_ajax.php';
  function picked(){ return Array.prototype.map.call(document.querySelectorAll('#bc-owners input:checked'), function(x){ return x.value; }); }
  function some(){ return type === 'consolidation' && own === 'some'; }
  function loadOwners(){ var cid = $('bc-cid').value; $('bc-owners').innerHTML = ''; if (!cid || own !== 'some') { $('bc-owners').style.display = 'none'; return; } $('bc-owners').style.display = ''; $('bc-owners').innerHTML = '<span class="mut sm">Loading owners…</span>';
    SL.get('ajax/select2_user_consolidation.php', { consolidation_id: cid, q: '' }).then(function(list){ $('bc-owners').innerHTML = (list || []).length ? list.map(function(u){ var d = document.createElement('span'); d.textContent = u.text; return '<label class="row g8 sm" style="cursor:pointer"><input type="checkbox" value="' + (+u.id) + '" checked> ' + d.innerHTML + '</label>'; }).join('') : '<span class="mut sm">No package owners in this consolidation.</span>'; ownCount(); }); }
  function ownCount(){ $('bc-own-n').textContent = some() ? picked().length + ' ticked' : ''; if (some()) { var n = picked().length; $('bc-reach').textContent = n + ' owner(s) ticked. Owners without a number or address are skipped and logged.'; $('bc-send').querySelector('span').textContent = 'Send to ' + n; } }
  $('bc-own').addEventListener('click', function(e){ var b = e.target.closest('button'); if (!b) return; own = b.getAttribute('data-v'); this.querySelectorAll('button').forEach(function(x){ x.classList.toggle('on', x === b); }); loadOwners(); if (!some()) { $('bc-own-n').textContent = ''; estimate(); } });
  $('bc-owners').addEventListener('change', ownCount);
  function base(){ return { notification_type: type, user_id: $('bc-uid').value, consolidation_id: $('bc-cid').value, channels: chans().join(','), subject: $('bc-subj').value, message: $('bc-msg').value, media_file: media }; }
  function view(){
    document.querySelectorAll('#bc-type button').forEach(function(b){ var on = b.getAttribute('data-v') === type; b.classList.toggle('on', on); if (on) $('bc-hint').textContent = b.getAttribute('data-hint'); });
    ['broadcast', 'single_user', 'consolidation'].forEach(function(k){ $('bc-to-' + k).style.display = k === type ? '' : 'none'; });
    var inv = type === 'invoice'; document.querySelectorAll('[data-bc-msg]').forEach(function(x){ x.style.display = inv ? 'none' : ''; }); $('bc-inv').style.display = inv ? '' : 'none';
    var c = chans(); document.querySelectorAll('[data-pv]').forEach(function(p){ p.style.display = c.indexOf(p.getAttribute('data-pv')) >= 0 ? '' : 'none'; }); $('bc-noch').hidden = c.length > 0;
    var m = $('bc-msg').value, s = $('bc-subj').value; document.querySelectorAll('[data-pv-m]').forEach(function(x){ x.textContent = m || 'Your message appears here.'; }); document.querySelectorAll('[data-pv-s]').forEach(function(x){ x.textContent = s; });
    var n = m.length; $('bc-count').textContent = n + ' characters · ' + Math.max(1, Math.ceil(n / 153)) + ' SMS part' + (n > 153 ? 's' : '');
  }
  var et; function estimate(){ clearTimeout(et); et = setTimeout(function(){ var p = base(); p.action = 'estimate'; if (type === 'invoice') return; if (some()) { ownCount(); return; } SL.post(AJ, p).then(function(j){ var a = j.audience || { total: 0, with_phone: 0, with_email: 0 }, c = chans(), cost = 0, bits = [];
    var parts = R.sms_per_part ? Math.max(1, Math.ceil($('bc-msg').value.length / 153)) : 1;
    if (c.indexOf('whatsapp') >= 0) { cost += a.with_phone * R.whatsapp; bits.push(a.with_phone + ' WhatsApp'); } if (c.indexOf('sms') >= 0) { cost += a.with_phone * R.sms * parts; bits.push(a.with_phone + ' SMS'); } if (c.indexOf('email') >= 0) { cost += a.with_email * R.email; bits.push(a.with_email + ' e-mails'); }
    $('bc-reach').textContent = a.total + ' recipient(s) · ' + a.with_phone + ' with a phone · ' + a.with_email + ' with an e-mail. Customers without a number or address are skipped and logged.';
    $('bc-cost').textContent = R.available ? 'About ' + R.currency + ' ' + cost.toFixed(2) : 'Cost: set unit prices in Message costs'; $('bc-costb').textContent = bits.join(' · '); $('bc-send').querySelector('span').textContent = 'Send to ' + a.total; }); }, 250); }
  document.addEventListener('click', function(e){ var b;
    if ((b = e.target.closest('#bc-type button'))) { type = b.getAttribute('data-v'); view(); estimate(); }
    else if ((b = e.target.closest('[data-ch]'))) { var on = !b.classList.contains('on'); b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); b.querySelector('.sl-chk').classList.toggle('on', on); view(); estimate(); }
    else if ((b = e.target.closest('[data-bc-pick]'))) { $('bc-uid').value = b.getAttribute('data-bc-pick'); $('bc-q').value = b.getAttribute('data-name'); $('bc-sug').innerHTML = ''; estimate(); }
  });
  var st; $('bc-q').addEventListener('input', function(){ var q = this.value; $('bc-uid').value = 0; clearTimeout(st); st = setTimeout(function(){ SL.post('ajax/sl/compose_ajax.php', { op: 'search', q: q }).then(function(j){ $('bc-sug').innerHTML = (j.items || []).map(function(it){ var d = document.createElement('div'); d.textContent = it.name; var n = d.innerHTML; d.textContent = it.sub; return '<button type="button" class="row g8 sm" style="text-align:left;padding:8px 10px;border:0;border-bottom:1px solid var(--line);background:var(--card);cursor:pointer" data-bc-pick="' + it.id + '" data-name="' + n.replace(/"/g, '&quot;') + '"><b class="fw5">' + n + '</b><span class="mut">' + d.innerHTML + '</span></button>'; }).join(''); }); }, 200); });
  ['bc-subj', 'bc-msg'].forEach(function(i){ $(i).addEventListener('input', function(){ view(); if (i === 'bc-msg') estimate(); }); }); $('bc-cid').addEventListener('change', function(){ estimate(); loadOwners(); });
  $('bc-file').addEventListener('change', function(){ var f = this.files[0]; if (!f) return; var fd = new FormData(); fd.append('media', f); $('bc-att').textContent = 'uploading…'; SL.post('ajax/tools/push_media_upload_ajax.php', fd).then(function(j){ if (j.success) { media = j.file; $('bc-att').textContent = f.name; document.querySelector('[data-pv-att]').hidden = false; document.querySelector('[data-pv-attn]').textContent = f.name; } else { $('bc-att').textContent = 'none'; SL.toast(j.message || 'Upload failed', true); } }); });
  $('bc-send').addEventListener('click', function(){ if (!chans().length) { SL.toast('Pick at least one channel', true); return; } if (!confirm('Send this push now?')) return; var btn = this, t = { s: 0, k: 0, f: 0, n: 0 }; btn.disabled = true; $('bc-prog').hidden = false;
    if (some() && !picked().length) { SL.toast('Tick at least one owner', true); btn.disabled = false; $('bc-prog').hidden = true; return; }
    (function step(after, batch){ var p = base(), url = AJ; p.after_id = after; p.batch_id = batch || ''; if (some()) { url = CJ; p = new FormData(); var b0 = base(); Object.keys(b0).forEach(function(k){ p.append(k, b0[k]); }); p.set('notification_type', 'selected_users'); p.append('after_id', after); p.append('batch_id', batch || ''); picked().forEach(function(u){ p.append('sender_ids[]', u); }); } SL.post(url, p).then(function(j){ if (!j.success) { var er = j.errors ? Object.values(j.errors).join(' ') : (j.message || 'Not sent'); SL.toast(er, true); btn.disabled = false; return; } var s = j.summary;
      ['whatsapp', 'email', 'sms'].forEach(function(c){ t.s += s[c].sent; t.k += s[c].skipped; t.f += s[c].failed; }); t.n += s.recipients; $('bc-s').textContent = t.s; $('bc-k').textContent = t.k; $('bc-f').textContent = t.f; $('bc-n').textContent = t.n + ' / ' + s.total; document.querySelector('.bc-bar i').style.width = Math.round(t.n / Math.max(1, s.total) * 100) + '%'; $('bc-logs').href = 'message_logs.php?batch_id=' + encodeURIComponent(s.batch_id);
      if (s.done) { btn.disabled = false; SL.toast('Push finished: ' + t.s + ' delivered, ' + t.f + ' failed'); } else step(s.next_after_id, s.batch_id); }).catch(function(){ SL.toast('Network error', true); btn.disabled = false; }); })(0, '');
  });

  /* ---------- invoice push (ajax/tools/push_notifications_invoice_ajax.php, action send_invoices) ---------- */
  var rows = [], rid = 0;
  function esc(t){ var d = document.createElement('div'); d.textContent = t == null ? '' : String(t); return d.innerHTML.replace(/"/g, '&quot;'); }
  function taken(except){ var s = {}; rows.forEach(function(r){ if (r.id !== except) r.oids.forEach(function(o){ s[o] = 1; }); }); return s; }
  function addRow(){ rows.push({ id: ++rid, uid: 0, name: '', pk: [], oids: [], amount: '' }); drawRows(); }
  function drawRows(){ $('bi-rows').innerHTML = rows.map(function(r, i){ var t = taken(r.id);
    return '<div class="sl-card col g8" data-bi="' + r.id + '" style="padding:12px"><div class="row between"><b class="fw5 sm">Customer ' + (i + 1) + '</b>' + (rows.length > 1 ? '<button type="button" class="sl-btn ghost sm" data-bi-del aria-label="Remove row"><i class="ic ic-sm i-trash" aria-hidden="true"></i></button>' : '') + '</div>'
      + '<div class="sl-search" style="max-width:none"><i class="ic ic-sm i-search" aria-hidden="true"></i><input data-bi-q aria-label="Customer" placeholder="Type a name, phone or locker" value="' + esc(r.name) + '"></div><div class="col" data-bi-sug></div>'
      + (r.uid ? '<div class="col g4"><span class="sl-lab">Packages</span>' + (r.pk.length ? r.pk.filter(function(p){ return !t[p.id]; }).map(function(p){ return '<label class="row g8 sm" style="cursor:pointer"><input type="checkbox" data-bi-o value="' + (+p.id) + '"' + (r.oids.indexOf(String(p.id)) >= 0 ? ' checked' : '') + '> <span class="mono">' + esc(p.text) + '</span>' + (p.postal_tracking ? ' <span class="mut">' + esc(p.postal_tracking) + '</span>' : '') + '</label>'; }).join('') : '<span class="mut sm">No packages for this customer in that date range.</span>') + '</div>' : '')
      + '<label class="sl-field"><span class="sl-lab">Amount</span><input class="sl-in" data-bi-a inputmode="decimal" placeholder="0.00" value="' + esc(r.amount) + '"></label></div>'; }).join(''); }
  function row(el){ var id = +el.closest('[data-bi]').getAttribute('data-bi'); return rows.filter(function(r){ return r.id === id; })[0]; }
  function loadPk(r){ SL.get('ajax/select2_user_orders.php', { sender_id: r.uid, ship_from: $('bi-from').value, ship_to: $('bi-to').value, q: '' }).then(function(list){ r.pk = list || []; r.oids = []; drawRows(); }); }
  var bst; $('bi-rows').addEventListener('input', function(e){ var r = row(e.target); if (e.target.matches('[data-bi-a]')) { r.amount = e.target.value; return; } if (!e.target.matches('[data-bi-q]')) return; var q = e.target.value, sug = e.target.closest('[data-bi]').querySelector('[data-bi-sug]'); r.name = q; clearTimeout(bst);
    bst = setTimeout(function(){ SL.post('ajax/sl/compose_ajax.php', { op: 'search', q: q }).then(function(j){ sug.innerHTML = (j.items || []).map(function(it){ return '<button type="button" class="row g8 sm" style="text-align:left;padding:8px 10px;border:0;border-bottom:1px solid var(--line);background:var(--card);cursor:pointer" data-bi-pick="' + (+it.id) + '" data-name="' + esc(it.name) + '"><b class="fw5">' + esc(it.name) + '</b><span class="mut">' + esc(it.sub) + '</span></button>'; }).join(''); }); }, 200); });
  $('bi-rows').addEventListener('change', function(e){ if (!e.target.matches('[data-bi-o]')) return; var r = row(e.target); r.oids = Array.prototype.map.call(e.target.closest('[data-bi]').querySelectorAll('[data-bi-o]:checked'), function(x){ return x.value; }); });
  $('bi-rows').addEventListener('click', function(e){ var b = e.target.closest('[data-bi-pick]'), r; if (b) { r = row(b); r.uid = +b.getAttribute('data-bi-pick'); r.name = b.getAttribute('data-name'); loadPk(r); return; } if (e.target.closest('[data-bi-del]')) { r = row(e.target); rows = rows.filter(function(x){ return x !== r; }); drawRows(); } });
  $('bi-add').addEventListener('click', addRow);
  ['bi-from', 'bi-to'].forEach(function(i){ $(i).addEventListener('change', function(){ rows.forEach(function(r){ if (r.uid) loadPk(r); }); }); });
  $('bi-send').addEventListener('click', function(){ var items = [], bad = false;
    rows.forEach(function(r){ var a = String(r.amount).replace(/,/g, '').trim(); if (!r.uid || !r.oids.length || a === '' || isNaN(parseFloat(a))) bad = true; else items.push({ sender_id: r.uid, order_ids: r.oids.map(Number), amount: a }); });
    if (bad || !items.length) { SL.toast('Pick a customer, at least one package and a valid amount on every row', true); return; }
    if (!$('bi-to').value || !$('bi-pick').value) { SL.toast('Set the shipments-to date and the pickup date', true); return; }
    if (!confirm('Send ' + items.length + ' invoice notification(s) now?')) return; var btn = this; btn.disabled = true;
    var fd = new FormData(); fd.append('action', 'send_invoices'); fd.append('shipment_from', $('bi-from').value); fd.append('shipment_end', $('bi-to').value); fd.append('pickup_date', $('bi-pick').value); fd.append('items', JSON.stringify(items));
    SL.post('ajax/tools/push_notifications_invoice_ajax.php', fd).then(function(j){ btn.disabled = false; var errs = j.errors ? (Array.isArray(j.errors) ? j.errors : Object.values(j.errors)) : [], msgs = j.messages || j.results || [];
      $('bi-res').innerHTML = (Array.isArray(msgs) ? msgs : []).concat(errs).map(function(m){ return '<span class="' + (j.success ? '' : 'mut') + '">' + esc(typeof m === 'string' ? m : JSON.stringify(m)) + '</span>'; }).join('');
      if (j.success) { SL.toast(j.message || 'Invoice notifications sent'); rows = []; addRow(); } else SL.toast(errs[0] || j.message || 'Not sent', true); }).catch(function(){ btn.disabled = false; SL.toast('Network error', true); }); });
  addRow();
  view(); estimate();
})();
</script>
